#include "types.h"

// arg0: 0x28/0x30 are the PS pair fields, 0x84/0x88 the lerp endpoints,
// 0x8C/0x90 the falloff radii.
typedef struct {
    char pad0x00[0x28];
    __ps_t ps28;
    __ps_t ps30;
    char pad0x38[0x4C];
    s32 i84;
    s32 i88;
    f32 f8C;
    f32 f90;
} A;

// return value of fn_80024660(): pair fields at +0x00 and +0x08.
typedef struct {
    __ps_t ps00;
    __ps_t ps08;
} Obj;

// Addressability is what buys the game's dead psq_st spills (see above).
typedef struct {
    __ps_t d0;
    __ps_t d1;
    SN_PS_type dot;
} Pair3;

extern s32 lbl_80300E00;
extern __ps_t lbl_80293FE8;
extern Obj *fn_8005DE90(s32);
extern Obj *fn_80024660(Obj *);

// squared distance from (a->ps28, a->ps30) to the live object, then a lerp
// between a->i88 and a->i84 clamped to lim.
s32 fn_80064294(A *a, s32 lim) {
    Pair3 tmp;
    __ps_t t3;
    __ps_t B;
    __ps_t D;
    __ps_t C;
    __ps_t E;
    __ps_t P;
    f32 d;
    f32 t;
    Obj *o;
    Obj *p;
    s32 res;

    if (a->f8C >= a->f90) {
        return lim;
    }
    if (lbl_80300E00 > 1) {
        return lim;
    }
    p = fn_8005DE90(0);
    if (p == 0) {
        return lim;
    }
    o = fn_80024660(p);
    B = o->ps08;
    D = a->ps30;
    C = o->ps00;
    E = lbl_80293FE8;
    P = a->ps28;
    tmp.d1 = __builtin_ps_sub(D, B);
    t3 = __builtin_ps_mul(tmp.d1, tmp.d1);
    tmp.d0 = __builtin_ps_sub(P, C);
    t3 = __builtin_ps_merge00(t3, E);
    tmp.dot.ps = __builtin_ps_madd(tmp.d0, tmp.d0, t3);
    tmp.dot.ps = __builtin_ps_sum0(tmp.dot.ps, tmp.dot.ps, tmp.dot.ps);
    d = tmp.dot.flt.hi;
    if (d < a->f8C) {
        return lim;
    }
    if (d > a->f90) {
        return a->i88;
    }
    t = (a->f90 - d) / (a->f90 - a->f8C);
    res = (s32)(a->i88 + t * (a->i84 - a->i88));
    if (res > lim) {
        res = lim;
    }
    return res;
}
